<#
  PDF Viewer - fix the icon of .pdf files in Windows Explorer.

  Chrome registers the installed PDF Viewer app as the .pdf handler, but Explorer
  can show a blank icon for .pdf files. This script:
    1. finds the program that currently opens .pdf files (must be PDF Viewer),
    2. saves the PDF Viewer file icon to %LOCALAPPDATA%\PDFViewer\file-pdf.ico,
    3. points that program's DefaultIcon at it (current user only, no admin),
    4. refreshes Explorer's icon cache.
  The previous value is backed up; run with -Undo to restore it.

  Run:  powershell -ExecutionPolicy Bypass -File .\fix-pdf-icon.ps1
#>
param([switch]$Undo)
$ErrorActionPreference = 'Stop'

$ext = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\FileExts\.pdf'
$prog = (Get-ItemProperty "$ext\UserChoiceLatest" -ErrorAction SilentlyContinue).ProgId
if (-not $prog) { $prog = (Get-ItemProperty "$ext\UserChoice" -ErrorAction SilentlyContinue).ProgId }
if (-not $prog) { Write-Host 'No default app is set for .pdf. Set PDF Viewer as default first (right-click a PDF > Open with > PDF Viewer > Always).' -ForegroundColor Yellow; exit 1 }

$classKey = "Registry::HKEY_CURRENT_USER\Software\Classes\$prog"
$openCmd  = (Get-ItemProperty "$classKey\shell\open\command" -ErrorAction SilentlyContinue).'(default)'
Write-Host "ProgId:  $prog"
Write-Host "Opens:   $openCmd"
if ($openCmd -notmatch 'chrome_proxy\.exe|--app-id') {
  Write-Host 'The default .pdf app is not an installed Chrome app (PDF Viewer). Nothing changed.' -ForegroundColor Yellow
  exit 1
}

$dir    = Join-Path $env:LOCALAPPDATA 'PDFViewer'
$ico    = Join-Path $dir 'file-pdf.ico'
$backup = Join-Path $dir 'defaulticon-backup.txt'
New-Item -ItemType Directory -Force -Path $dir | Out-Null
$iconKey = "$classKey\DefaultIcon"
$current = (Get-ItemProperty $iconKey -ErrorAction SilentlyContinue).'(default)'
Write-Host "Current DefaultIcon: $current"
if ($current) {
  $p = ($current -split ',')[0].Trim('"')
  Write-Host ("Current icon file exists: " + (Test-Path $p))
}

if ($Undo) {
  if (-not (Test-Path $backup)) { Write-Host 'No backup found.' -ForegroundColor Yellow; exit 1 }
  $old = Get-Content $backup -Raw
  if ($old.Trim()) { Set-ItemProperty -Path $iconKey -Name '(default)' -Value $old.Trim() }
  else { Remove-Item $iconKey -Recurse -ErrorAction SilentlyContinue }
  Write-Host 'Restored the previous icon setting.' -ForegroundColor Green
} else {
  if (-not (Test-Path $backup)) { Set-Content -Path $backup -Value ([string]$current) -NoNewline }
  $b64 = @"
