"@
  [IO.File]::WriteAllBytes($ico, [Convert]::FromBase64String(($b64 -replace '\s','')))
  if (-not (Test-Path $iconKey)) { New-Item -Path $iconKey -Force | Out-Null }
  Set-ItemProperty -Path $iconKey -Name '(default)' -Value "`"$ico`",0"
  Write-Host "New DefaultIcon: `"$ico`",0" -ForegroundColor Green
}

# Refresh Explorer's icons
Add-Type -Namespace Win32 -Name Shell -MemberDefinition '[DllImport("shell32.dll")] public static extern void SHChangeNotify(int e, int f, System.IntPtr a, System.IntPtr b);'
[Win32.Shell]::SHChangeNotify(0x08000000, 0, [IntPtr]::Zero, [IntPtr]::Zero)
Start-Process -FilePath "$env:WINDIR\System32\ie4uinit.exe" -ArgumentList '-show' -Wait -ErrorAction SilentlyContinue
Write-Host 'Done. If icons still look blank, restart Windows Explorer (Task Manager > Windows Explorer > Restart).'
